# clustree: Seurat Louvain resolution sweep on Zeisel 2015 (tree of cluster splits, overlaid on UMAP, marker-coloured)
suppressPackageStartupMessages({library(clustree); library(Seurat); library(ggplot2)})
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE)))); if (!file.exists("../_data/zeisel_markers.csv")) system("Rscript ../_data/zeisel_de.R")
so <- readRDS("../_data/zeisel_seurat.rds"); so <- FindClusters(so, resolution = c(.1,.2,.4,.6,.8,1.2), verbose = FALSE)
ggsave("v1_clustree_tree.png", clustree(so, prefix = "RNA_snn_res.") + ggtitle("clustree: resolution sweep (Zeisel 2015)"), width = 9, height = 9, dpi = 130, bg = "white")
ggsave("v2_clustree_sc3stability.png", clustree(so, prefix = "RNA_snn_res.", node_colour = "sc3_stability") + scale_colour_viridis_c(option = "magma"), width = 9, height = 9, dpi = 130, bg = "white")
ggsave("v3_clustree_gene_Mbp.png", clustree(so, prefix = "RNA_snn_res.", node_colour = "Mbp", node_colour_aggr = "median") + scale_colour_distiller(palette = "YlOrRd", direction = 1) + ggtitle("node colour = median Mbp"), width = 9, height = 9, dpi = 130, bg = "white")
um <- Embeddings(so, "umap"); colnames(um) <- c("UMAP_1","UMAP_2"); so@meta.data <- cbind(so@meta.data, um)
ggsave("v4_clustree_overlay.png", clustree_overlay(so@meta.data, prefix = "RNA_snn_res.", x_value = "UMAP_1", y_value = "UMAP_2", red_dim = "umap") + theme_bw() + ggtitle("clustree_overlay on UMAP"), width = 8, height = 7, dpi = 130, bg = "white")
